// ---- 01-core.js
// هستهٔ پلاگین: وضعیت مشترک، رنگ، فونت و چیدمان راست‌به‌چپ

const S = {
  /** فونت هر وزن: { regular: {family, style}, ... } */
  fonts: {},
  family: TOKENS.font.family,
  /** متغیرها بر اساس نام کامل، مثل "bg-brand" یا "radius/md" */
  vars: {},
  collections: {},
  textStyles: {},
  effectStyles: {},
  /** استایل متن و افکت آخر کار به‌صورت async وصل می‌شوند */
  pendingText: [],
  pendingEffect: [],
  icons: {},
  bankLogos: {},
  theme: "dark",
  stats: { variables: 0, textStyles: 0, effectStyles: 0, components: 0, sets: 0 },
};

/** جایگزین ?? (محیط اجرای پلاگین فیگما همهٔ نحوهای جدید را ندارد) */
const pick = (a, b) => (a === undefined || a === null ? b : a);

// ---------- رنگ ----------
const rgb = ([r, g, b]) => ({ r, g, b });
const paletteHex = (scale, step) => TOKENS.palette[scale === "brand" ? TOKENS.brandScale : scale][step];
function hexToRgba(h) {
  const s = h.replace("#", "");
  const n = (i) => parseInt(s.slice(i, i + 2), 16) / 255;
  return [n(0), n(2), n(4), 1];
}
/** مقدار واقعی یک توکن معنایی در تم */
function themeRgba(token, mode = S.theme) {
  const v = TOKENS.themes[mode][token];
  if (!v) throw new Error(`Unknown color token: ${token}`);
  return v.rgba ? v.rgba : hexToRgba(paletteHex(v.alias[0], v.alias[1]));
}

/**
 * رنگ برای fills و strokes:
 * "bg-brand" → متغیر تم؛ "firoozeh/500" → متغیر پالت؛ "#fff" یا [r,g,b,a] → رنگ ثابت.
 * opacity اختیاری روی خود paint اعمال می‌شود.
 */
function paint(c, opacity) {
  let rgba, variable;
  if (Array.isArray(c)) rgba = c;
  else if (c.startsWith("#")) rgba = hexToRgba(c);
  else if (c.includes("/")) {
    const [scale, step] = c.split("/");
    rgba = hexToRgba(paletteHex(scale, step));
    variable = S.vars[`color/${scale}/${step}`];
  } else {
    rgba = themeRgba(c);
    variable = S.vars[c];
  }
  let p = { type: "SOLID", color: rgb(rgba), opacity: pick(opacity, 1) * rgba[3] };
  if (variable) {
    // وقتی رنگ به متغیر وصل است، آلفا از خود متغیر می‌آید
    p = figma.variables.setBoundVariableForPaint({ type: "SOLID", color: rgb(rgba), opacity: pick(opacity, 1) }, "color", variable);
  }
  return p;
}

// ---------- فونت ----------
const WEIGHTS = ["light", "regular", "medium", "semibold", "bold", "black"];
const STYLE_ALIASES = {
  light: ["light"],
  regular: ["regular", "normal", "book", "roman"],
  medium: ["medium"],
  semibold: ["semibold", "demibold", "demi"],
  bold: ["bold"],
  black: ["black", "heavy", "extrabold"],
};
const norm = (s) => s.toLowerCase().replace(/[\s_-]/g, "");

/** وزن‌های فونت انتخابی را پیدا و بارگذاری می‌کند؛ وزن ناموجود به نزدیک‌ترین وزن می‌افتد */
async function loadFonts(family) {
  const all = await figma.listAvailableFontsAsync();
  const pick = (fam) => {
    const styles = all.filter((f) => norm(f.fontName.family) === norm(fam)).map((f) => f.fontName);
    if (!styles.length) return null;
    const found = {};
    for (const w of WEIGHTS) {
      found[w] = styles.find((f) => STYLE_ALIASES[w].includes(norm(f.style)));
    }
    return found.regular ? found : null;
  };
  let found = pick(family);
  let usedFamily = family;
  if (!found) {
    found = pick("Vazirmatn") || pick("Inter");
    usedFamily = found ? found.regular.family : "Inter";
  }
  if (!found) throw new Error("No usable font found");
  const order = ["regular", "medium", "semibold", "bold", "black", "light"];
  for (const w of WEIGHTS) {
    if (!found[w]) {
      // نزدیک‌ترین وزن موجود
      const i = order.indexOf(w);
      found[w] = [...order.slice(0, i).reverse(), ...order.slice(i)].map((x) => found[x]).find(Boolean);
    }
  }
  await Promise.all(Object.values(found).map((f) => figma.loadFontAsync(f)));
  S.fonts = found;
  S.family = usedFamily;
  return usedFamily;
}

// ---------- چیدمان ----------
/** تنظیم اندازهٔ فرزند داخل auto layout؛ بعد از append قابل اعمال است */
const SIZING = new WeakMap();
const ALIGN = { start: "MAX", center: "CENTER", end: "MIN", between: "SPACE_BETWEEN" };
const ALIGN_V = { start: "MIN", center: "CENTER", end: "MAX", between: "SPACE_BETWEEN" };
const CROSS_H = { start: "MAX", center: "CENTER", end: "MIN", baseline: "BASELINE" };
const CROSS_V = { start: "MIN", center: "CENTER", end: "MAX", baseline: "BASELINE" };

function bindNum(node, field, value) {
  const v = typeof value === "string" ? S.vars[value] : null;
  if (v) {
    try { node.setBoundVariable(field, v); return; } catch (e) { /* فیلد پشتیبانی نمی‌شود */ }
  }
  node[field] = typeof value === "string" ? numOf(value) : value;
}
/** مقدار عددی "space/4" یا "radius/md" */
function numOf(name) {
  const [group, key] = name.split("/");
  if (group === "space") return TOKENS.space[key];
  if (group === "radius") return TOKENS.radius[key];
  if (S.numbers[name] !== undefined) return S.numbers[name];
  throw new Error(`Unknown number token: ${name}`);
}
S.numbers = {};

function setRadius(node, r) {
  if (r === undefined) return;
  if (Array.isArray(r)) {
    // [شروع-بالا, پایان-بالا, پایان-پایین, شروع-پایین] منطقی؛ شروع = راست
    const [ss, se, ee, es] = r;
    bindNum(node, "topRightRadius", ss);
    bindNum(node, "topLeftRadius", se);
    bindNum(node, "bottomLeftRadius", ee);
    bindNum(node, "bottomRightRadius", es);
    return;
  }
  for (const f of ["topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius"]) bindNum(node, f, r);
}

function effectStyle(node, name) {
  if (!name) return;
  const names = Array.isArray(name) ? name : [name];
  const list = names.map((n) => S.effectStyles[`${S.theme === "dark" ? "Dark" : "Light"}/${n}`] || S.effectStyles[n]).filter(Boolean);
  if (!list.length) return;
  if (list.length === 1) S.pendingEffect.push([node, list[0].id]);
  else node.effects = list.flatMap((s) => s.effects);
}

/**
 * فریم با auto layout راست‌به‌چپ.
 * o: { name, dir: "H"|"V"|"none", gap, p, px, py, pt, pb, ps, pe, w, h, align, cross, fill, stroke, sw, radius, shadow, clip, wrap, opacity }
 * w/h: عدد = ثابت، "fill" = پرکردن والد، "hug" = به اندازهٔ محتوا (پیش‌فرض)
 */
function F(o = {}, children = []) {
  const f = figma.createFrame();
  f.name = o.name || "Frame";
  f.fills = o.fill ? [paint(o.fill, o.fillOpacity)] : [];
  f.clipsContent = !!o.clip;
  const dir = o.dir || "H";
  if (dir !== "none") {
    f.layoutMode = dir === "H" ? "HORIZONTAL" : "VERTICAL";
    if (o.wrap) f.layoutWrap = "WRAP";
    if (o.gap !== undefined) bindNum(f, "itemSpacing", o.gap);
    if (o.wrap && o.rowGap !== undefined) bindNum(f, "counterAxisSpacing", o.rowGap);
    const pad = (k, v) => v !== undefined && bindNum(f, k, v);
    const px = pick(o.px, o.p), py = pick(o.py, o.p);
    pad("paddingTop", pick(o.pt, py));
    pad("paddingBottom", pick(o.pb, py));
    // RTL: شروع = راست
    pad("paddingRight", pick(o.ps, px));
    pad("paddingLeft", pick(o.pe, px));
    if (dir === "H") {
      f.primaryAxisAlignItems = ALIGN[o.align || "start"];
      f.counterAxisAlignItems = CROSS_V[o.cross || "center"];
    } else {
      f.primaryAxisAlignItems = ALIGN_V[o.align || "start"];
      f.counterAxisAlignItems = CROSS_H[o.cross || "start"];
    }
  }
  if (o.stroke) {
    f.strokes = [paint(o.stroke, o.strokeOpacity)];
    f.strokeAlign = o.strokeAlign || "INSIDE";
    if (o.sides) {
      const [t, r, b, l] = o.sides;
      f.strokeTopWeight = t; f.strokeRightWeight = r; f.strokeBottomWeight = b; f.strokeLeftWeight = l;
    } else f.strokeWeight = pick(o.sw, 1);
    if (o.dash) f.dashPattern = o.dash;
  }
  setRadius(f, o.radius);
  effectStyle(f, o.shadow);
  if (o.opacity !== undefined) f.opacity = o.opacity;

  // RTL: در فیگما ترتیب افقی چپ‌به‌راست است، پس فرزندان را برعکس می‌چینیم
  const kids = children.flat(Infinity).filter(Boolean);
  const ordered = dir === "H" ? kids.slice().reverse() : kids;
  for (const k of ordered) f.appendChild(k);
  sizeSelf(f, o, dir);
  if (dir !== "none") for (const k of kids) applySizing(k);
  else {
    // چیدمان آزاد: مختصات منطقی x از راست
    const W = typeof o.w === "number" ? o.w : 100;
    for (const k of kids) {
      const s = SIZING.get(k) || {};
      if (s.x !== undefined) k.x = W - s.x - k.width;
      if (s.y !== undefined) k.y = s.y;
    }
  }
  return f;
}

function sizeSelf(f, o, dir) {
  const W = o.w, H = o.h;
  if (dir === "none") {
    f.resize(typeof W === "number" ? W : 100, typeof H === "number" ? H : 100);
  } else {
    const fixedW = typeof W === "number" || (typeof W === "string" && S.vars[W]);
    const fixedH = typeof H === "number" || (typeof H === "string" && S.vars[H]);
    const horizontal = f.layoutMode === "HORIZONTAL";
    f.primaryAxisSizingMode = (horizontal ? fixedW : fixedH) ? "FIXED" : "AUTO";
    f.counterAxisSizingMode = (horizontal ? fixedH : fixedW) ? "FIXED" : "AUTO";
    if (fixedW || fixedH) {
      const w = typeof W === "number" ? W : fixedW ? numOf(W) : f.width;
      const h = typeof H === "number" ? H : fixedH ? numOf(H) : f.height;
      f.resize(Math.max(w, 0.01), Math.max(h, 0.01));
      if (typeof W === "string" && S.vars[W]) bindNum(f, "width", W);
      if (typeof H === "string" && S.vars[H]) bindNum(f, "height", H);
    }
    if (o.minW) f.minWidth = o.minW;
    if (o.maxW) f.maxWidth = o.maxW;
  }
  SIZING.set(f, { w: W, h: H, x: o.x, y: o.y, absolute: o.absolute, grow: o.grow });
}

function applySizing(k) {
  const s = SIZING.get(k);
  if (!s) return;
  const parent = k.parent;
  if (!parent || parent.layoutMode === "NONE") return;
  if (s.absolute) {
    k.layoutPositioning = "ABSOLUTE";
    if (s.x !== undefined) k.x = parent.width - s.x - k.width;
    if (s.y !== undefined) k.y = s.y;
    return;
  }
  try {
    if (s.w === "fill") k.layoutSizingHorizontal = "FILL";
    else if (s.w === "hug" && (k.type === "TEXT" || k.layoutMode !== "NONE")) k.layoutSizingHorizontal = "HUG";
    if (s.h === "fill") k.layoutSizingVertical = "FILL";
    if (s.grow) k.layoutGrow = 1;
  } catch (e) { /* نوع گره اجازه نمی‌دهد */ }
}

/** متن فارسی؛ s: { style: "Text sm/Medium", color, align, w, maxLines, name } */
function T(text, o = {}) {
  const t = figma.createText();
  const style = S.textStyles[o.style || "Text sm/Regular"];
  const spec = style ? style.spec : { size: TOKENS.font.size.sm, weight: "regular", leading: TOKENS.font.leading.normal };
  t.fontName = S.fonts[o.weight || spec.weight];
  t.fontSize = o.size || spec.size;
  t.lineHeight = { unit: "PIXELS", value: Math.round((o.size || spec.size) * (o.leading || spec.leading)) };
  t.characters = String(text);
  t.name = o.name || String(text).slice(0, 40);
  t.fills = [paint(o.color || "text-primary")];
  t.textAlignHorizontal = { start: "RIGHT", center: "CENTER", end: "LEFT", justify: "JUSTIFIED" }[o.align || "start"];
  if (o.ltr) t.textAlignHorizontal = o.align === "center" ? "CENTER" : "LEFT";
  t.textAutoResize = o.w === "fill" || typeof o.w === "number" ? "HEIGHT" : "WIDTH_AND_HEIGHT";
  if (typeof o.w === "number") t.resize(o.w, t.height);
  if (o.maxLines) { t.textTruncation = "ENDING"; t.maxLines = o.maxLines; }
  if (o.decoration) t.textDecoration = o.decoration;
  if (o.letterSpacing) t.letterSpacing = { unit: "PERCENT", value: o.letterSpacing };
  if (style && !o.size && !o.weight && !o.leading) S.pendingText.push([t, style.node.id]);
  SIZING.set(t, { w: o.w, h: o.h, x: o.x, y: o.y, absolute: o.absolute, grow: o.grow });
  return t;
}

/** مستطیل/بیضی ساده */
function R(o = {}) {
  const r = o.ellipse ? figma.createEllipse() : figma.createRectangle();
  r.name = o.name || (o.ellipse ? "Dot" : "Rect");
  r.resize(pick(o.w, 8), pick(o.h, 8));
  r.fills = o.fill ? [paint(o.fill, o.fillOpacity)] : [];
  if (o.stroke) { r.strokes = [paint(o.stroke)]; r.strokeWeight = pick(o.sw, 1); r.strokeAlign = "INSIDE"; }
  if (!o.ellipse) setRadius(r, o.radius);
  if (o.ellipse && o.arc) r.arcData = o.arc;
  if (o.rotation) r.rotation = o.rotation;
  effectStyle(r, o.shadow);
  SIZING.set(r, { w: o.fillW ? "fill" : undefined, h: o.fillH ? "fill" : undefined, x: o.x, y: o.y, absolute: o.absolute, grow: o.grow });
  return r;
}

/** جای خالی منعطف */
const Spacer = () => F({ name: "Spacer", grow: true, w: 1, h: 1 });

// ---------- ارقام فارسی ----------
const FA = "۰۱۲۳۴۵۶۷۸۹";
const fa = (v) => String(v).replace(/\d/g, (d) => FA[d]);
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

/** افزودن فرزند به فریم موجود با رعایت RTL و اندازه‌دهی */
function add(parent, ...kids) {
  for (const k of kids.flat(Infinity)) {
    if (!k) continue;
    if (parent.layoutMode === "HORIZONTAL" && parent.layoutWrap !== "WRAP") parent.insertChild(0, k);
    else parent.appendChild(k);
    applySizing(k);
  }
  return parent;
}

// ---- 02-variables.js
// متغیرها (Variables)، استایل‌های متن و افکت — همه از روی توکن‌های @kashi-ui/tokens

let existingVars = null;
let existingCollections = null;

async function getCollection(name, modes) {
  existingCollections = existingCollections || (await figma.variables.getLocalVariableCollectionsAsync());
  let c = existingCollections.find((x) => x.name === name);
  if (!c) c = figma.variables.createVariableCollection(name);
  // نام mode ها را یکی می‌کند و mode های کم را می‌سازد
  const ids = {};
  modes.forEach((m, i) => {
    if (c.modes[i]) {
      if (c.modes[i].name !== m) c.renameMode(c.modes[i].modeId, m);
      ids[m] = c.modes[i].modeId;
    } else {
      // پلن رایگان فیگما فقط یک mode دارد؛ بقیه را بی‌صدا رد می‌کنیم
      try { ids[m] = c.addMode(m); } catch (e) { S.limitedModes = true; }
    }
  });
  S.collections[name] = { node: c, modes: ids };
  return { c, ids };
}

/** مقدار برای mode؛ اگر mode ساخته نشده باشد (پلن رایگان) رد می‌شود */
function setVal(v, ids, mode, value) {
  if (ids[mode]) v.setValueForMode(ids[mode], value);
}

async function getVariable(c, name, type, scopes) {
  existingVars = existingVars || (await figma.variables.getLocalVariablesAsync());
  let v = existingVars.find((x) => x.name === name && x.variableCollectionId === c.id);
  if (!v) {
    v = figma.variables.createVariable(name, c, type);
    existingVars.push(v);
  }
  if (scopes) v.scopes = scopes;
  S.stats.variables++;
  return v;
}

const COLOR_SCOPES = {
  bg: ["FRAME_FILL", "SHAPE_FILL"],
  text: ["TEXT_FILL"],
  border: ["STROKE_COLOR"],
};
const rgbaObj = ([r, g, b, a]) => ({ r, g, b, a });

async function buildVariables() {
  existingVars = null;
  existingCollections = null;

  // ---- پالت
  const prim = await getCollection("Kashi · Primitives", ["Value"]);
  for (const [scale, steps] of Object.entries(TOKENS.palette)) {
    for (const [step, hex] of Object.entries(steps)) {
      const v = await getVariable(prim.c, `color/${scale}/${step}`, "COLOR", ["ALL_SCOPES"]);
      v.setValueForMode(prim.ids.Value, rgbaObj(hexToRgba(hex)));
      S.vars[`color/${scale}/${step}`] = v;
    }
  }
  // brand فقط نام مستعار است؛ برای عوض کردن رنگ برند این‌ها را به پالت دیگری وصل کنید
  for (const step of Object.keys(TOKENS.palette[TOKENS.brandScale])) {
    const v = await getVariable(prim.c, `color/brand/${step}`, "COLOR", ["ALL_SCOPES"]);
    v.setValueForMode(prim.ids.Value, figma.variables.createVariableAlias(S.vars[`color/${TOKENS.brandScale}/${step}`]));
    v.description = "رنگ برند — برای تغییر برند، این را به یک رنگ دیگر از پالت وصل کنید";
    S.vars[`color/brand/${step}`] = v;
  }

  // ---- تم تیره و روشن
  const theme = await getCollection("Kashi · Theme", S.theme === "light" ? ["Light", "Dark"] : ["Dark", "Light"]);
  for (const token of Object.keys(TOKENS.themes.dark)) {
    const scopes = COLOR_SCOPES[token.split("-")[0]] || ["ALL_SCOPES"];
    const v = await getVariable(theme.c, token.replace(/^(bg|text|border)-/, "$1/"), "COLOR", scopes);
    for (const [mode, key] of [["Dark", "dark"], ["Light", "light"]]) {
      const val = TOKENS.themes[key][token];
      setVal(v, theme.ids, mode, val.alias ? figma.variables.createVariableAlias(S.vars[`color/${val.alias[0]}/${val.alias[1]}`]) : rgbaObj(val.rgba));
    }
    S.vars[token] = v;
  }

  // ---- گردی گوشه‌ها با چهار حالت (همان --k-radius-factor)
  const radius = await getCollection("Kashi · Radius", ["Default", "Sharp", "Soft", "Round"]);
  const factors = { Default: 1, Sharp: 0, Soft: 0.5, Round: 1.75 };
  const radii = Object.assign({}, TOKENS.radius, { checkbox: 5 });
  for (const [k, base] of Object.entries(radii)) {
    const v = await getVariable(radius.c, `radius/${k}`, "FLOAT", ["CORNER_RADIUS"]);
    for (const [mode, f] of Object.entries(factors)) setVal(v, radius.ids, mode, k === "full" ? 9999 : base * f);
    S.vars[`radius/${k}`] = v;
    S.numbers[`radius/${k}`] = base;
  }

  // ---- فاصله‌ها
  const space = await getCollection("Kashi · Spacing", ["Value"]);
  for (const [k, val] of Object.entries(TOKENS.space)) {
    const v = await getVariable(space.c, `space/${k.replace(".", "_")}`, "FLOAT", ["GAP", "WIDTH_HEIGHT"]);
    v.setValueForMode(space.ids.Value, val);
    S.vars[`space/${k}`] = v;
  }

  // ---- تراکم: ارتفاع و فاصلهٔ داخلی کنترل‌ها (همان --k-density)
  const density = await getCollection("Kashi · Density", ["Default", "Compact", "Comfortable"]);
  const dens = { Default: 1, Compact: 0.875, Comfortable: 1.125 };
  const controls = {
    "control/height/xs": 28, "control/height/sm": 36, "control/height/md": 40, "control/height/lg": 44, "control/height/xl": 48,
    "control/padding/xs": 8, "control/padding/sm": 12, "control/padding/md": 14, "control/padding/lg": 18, "control/padding/xl": 20,
    "input/height/sm": 36, "input/height/md": 40, "input/height/lg": 44, "input/padding": 14,
    "card/padding/sm": 16, "card/padding/md": 24, "card/padding/lg": 32,
    "menu/item-height": 36, "tab/height": 40, "alert/padding": 16,
  };
  for (const [k, base] of Object.entries(controls)) {
    const v = await getVariable(density.c, k, "FLOAT", [k.includes("height") ? "WIDTH_HEIGHT" : "GAP"]);
    for (const [mode, f] of Object.entries(dens)) setVal(v, density.ids, mode, Math.round(base * f));
    S.vars[k] = v;
    S.numbers[k] = base;
  }

  // ---- تایپوگرافی؛ فونت دلخواه (حتی فونت پولی) با عوض کردن یک متغیر
  const typo = await getCollection("Kashi · Typography", ["Default", "Compact", "Large"]);
  const scales = { Default: 1, Compact: 0.9375, Large: 1.125 };
  const fam = await getVariable(typo.c, "font/family/sans", "STRING", ["FONT_FAMILY"]);
  const disp = await getVariable(typo.c, "font/family/display", "STRING", ["FONT_FAMILY"]);
  for (const mode of Object.keys(typo.ids)) {
    setVal(fam, typo.ids, mode, S.family);
    setVal(disp, typo.ids, mode, S.family);
  }
  fam.description = "نام فونت متن؛ هر فونتی که روی سیستم نصب است (مثل IRANSans یا Yekan Bakh)";
  S.vars["font/family/sans"] = fam;
  S.vars["font/family/display"] = disp;
  for (const w of WEIGHTS) {
    const v = await getVariable(typo.c, `font/weight/${w}`, "STRING", ["FONT_STYLE"]);
    for (const mode of Object.keys(typo.ids)) setVal(v, typo.ids, mode, S.fonts[w].style);
    S.vars[`font/weight/${w}`] = v;
  }
  for (const [k, size] of Object.entries(TOKENS.font.size)) {
    const v = await getVariable(typo.c, `font/size/${k}`, "FLOAT", ["FONT_SIZE"]);
    for (const [mode, f] of Object.entries(scales)) setVal(v, typo.ids, mode, Math.round(size * f));
    S.vars[`font/size/${k}`] = v;
    for (const [kind, leading] of [["text", TOKENS.font.leading.normal], ["display", TOKENS.font.leading.tight]]) {
      const lh = await getVariable(typo.c, `font/line-height/${kind}-${k}`, "FLOAT", ["LINE_HEIGHT"]);
      for (const [mode, f] of Object.entries(scales)) setVal(lh, typo.ids, mode, Math.round(size * f * leading));
      S.vars[`font/line-height/${kind}-${k}`] = lh;
    }
  }
}

// ---------- استایل متن ----------
const TEXT_WEIGHTS = { Regular: "regular", Medium: "medium", Semibold: "semibold", Bold: "bold" };

async function buildTextStyles() {
  const existing = await figma.getLocalTextStylesAsync();
  const make = async (name, sizeKey, weight, kind) => {
    let st = existing.find((s) => s.name === name);
    if (!st) st = figma.createTextStyle();
    st.name = name;
    const size = TOKENS.font.size[sizeKey];
    const leading = kind === "display" ? TOKENS.font.leading.tight : TOKENS.font.leading.normal;
    st.fontName = S.fonts[weight];
    st.fontSize = size;
    st.lineHeight = { unit: "PIXELS", value: Math.round(size * leading) };
    st.letterSpacing = { unit: "PERCENT", value: kind === "display" && size >= 36 ? -1 : 0 };
    st.description = `${size}px · ${weight} · line-height ${leading}`;
    const bind = (field, key) => { try { if (S.vars[key]) st.setBoundVariable(field, S.vars[key]); } catch (e) { /* قدیمی */ } };
    bind("fontFamily", kind === "display" ? "font/family/display" : "font/family/sans");
    bind("fontStyle", `font/weight/${weight}`);
    bind("fontSize", `font/size/${sizeKey}`);
    bind("lineHeight", `font/line-height/${kind}-${sizeKey}`);
    S.textStyles[name] = { node: st, spec: { size, weight, leading } };
    S.stats.textStyles++;
  };
  for (const sizeKey of ["6xl", "5xl", "4xl", "3xl", "2xl", "xl"]) {
    for (const [label, w] of Object.entries(TEXT_WEIGHTS)) await make(`Display ${sizeKey}/${label}`, sizeKey, w, "display");
  }
  for (const sizeKey of ["xl", "lg", "md", "sm", "xs"]) {
    for (const [label, w] of Object.entries(TEXT_WEIGHTS)) await make(`Text ${sizeKey}/${label}`, sizeKey, w, "text");
  }
}

// ---------- استایل افکت ----------
function toEffect(e) {
  const out = { type: e.type, color: rgbaObj(e.rgba), offset: { x: e.x, y: e.y }, radius: e.blur, spread: e.spread, visible: true, blendMode: "NORMAL" };
  if (e.type === "DROP_SHADOW") out.showShadowBehindNode = false;
  return out;
}

async function buildEffectStyles() {
  const existing = await figma.getLocalEffectStylesAsync();
  const make = (name, list, description) => {
    let st = existing.find((s) => s.name === name);
    if (!st) st = figma.createEffectStyle();
    st.name = name;
    st.effects = list.map(toEffect);
    if (description) st.description = description;
    S.effectStyles[name] = st;
    S.stats.effectStyles++;
  };
  for (const [mode, label] of [["dark", "Dark"], ["light", "Light"]]) {
    const E = TOKENS.effects[mode];
    for (const k of ["xs", "sm", "md", "lg", "xl", "2xl"]) make(`${label}/Shadow/${k}`, E[`shadow-${k}`]);
    make(`${label}/Focus ring/brand`, E["ring-brand"], "حلقهٔ فوکوس نرم (WCAG 2.4.7)");
    make(`${label}/Focus ring/error`, E["ring-error"]);
    make(`${label}/Skeuomorphic`, E["shadow-skeuomorphic"]);
    // ترکیب‌های آماده برای کامپوننت‌ها
    make(`${label}/Button`, [...E["shadow-xs"], ...E["shadow-skeuomorphic"]], "سایهٔ اسکئومورفیک دکمه");
    make(`${label}/Button focus`, [...E["shadow-xs"], ...E["shadow-skeuomorphic"], ...E["ring-brand"]]);
    make(`${label}/Button danger focus`, [...E["shadow-xs"], ...E["shadow-skeuomorphic"], ...E["ring-error"]]);
    make(`${label}/Input focus`, [...E["shadow-xs"], ...E["ring-brand"]]);
    make(`${label}/Input error focus`, [...E["shadow-xs"], ...E["ring-error"]]);
    make(`${label}/Elevated`, [...E["shadow-lg"], ...E.highlight]);
    make(`${label}/Popover`, [...E["shadow-xl"], ...E.highlight]);
  }
}

